1403	// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
1404	// Works correctly from any subdirectory within the repository.
1405	func EnsureEntireGitignore(ctx context.Context) error {
1406		// Open (creating if needed) the shared .entire root; the gitignore lives at
1407		// its top level, so the root is also the directory this would have created.
1408		root, err := entiredir.Open(ctx)
1409		if err != nil {
1410			return fmt.Errorf("failed to create .entire directory: %w", err)
1411		}
1412		gitignoreName := entiredir.MustName(entireGitignore)
1413	
1414		// Read existing content
1415		var content string
1416		if data, rerr := entiredir.ReadFile(root, gitignoreName); rerr == nil {
1417			content = string(data)
1418		}
1419	
1420		// All entries that should be in .entire/.gitignore
1421		requiredEntries := []string{
1422			"tmp/",
1423			"settings.local.json",
1424			"metadata/",
1425			"logs/",
1426			redact.RedactorsDirName + "/local/",
1427		}
1428	
1429		// Track what needs to be added
1430		var toAdd []string
1431		for _, entry := range requiredEntries {
1432			if !strings.Contains(content, entry) {
1433				toAdd = append(toAdd, entry)
1434			}
1435		}
1436	
1437		// Nothing to add
1438		if len(toAdd) == 0 {
1439			return nil
1440		}
1441	
1442		// Append missing entries to gitignore
1443		var sb strings.Builder
1444		for _, entry := range toAdd {
1445			sb.WriteString(entry + "\n")
1446		}
1447		content += sb.String()
1448	
1449		if err := entiredir.WriteFile(root, gitignoreName, []byte(content), 0o644); err != nil {
1450			return fmt.Errorf("failed to write gitignore: %w", err)
1451		}
1452		return nil
1453	}
